def top_words(text, top=5):
    """The most common words, most common first, ties alphabetical."""
    counts = {}
    for word in words(text):
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1
    ranked = []
    for word in counts:
        ranked.append((-counts[word], word))
    ranked.sort()
    result = []
    for negative_count, word in ranked[:top]:
        result.append((word, -negative_count))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", help="the text file to read")
    parser.add_argument(
        "--top", type=int, default=5, help="how many words to print (default: 5)"
    )
    args = parser.parse_args(argv)
    if args.top < 1:
        parser.error("--top must be >= 1")
    with open(args.path, encoding="utf-8") as handle:
        text = handle.read()
    for word, count in top_words(text, args.top):
        print(f"{count:>5}  {word}")
    return 0
